"use client";

import { type CurveFactory, curveLinear } from "d3-shape";
import { useCallback, useId, useMemo } from "react";
import { useChart, useChartStable } from "./chart-context";
import {
  type FadeEdges,
  fadeGradientStops,
  resolveFadeSides,
} from "./fade-edges";
import { LinePath, linePathD } from "./line-path";
import { useProfitLossLegendHover } from "./profit-loss-legend-hover";

/** Semantic trend tokens with Tailwind fallbacks for apps without `--chart-positive` / `--chart-negative`. */
export const PROFIT_LOSS_POSITIVE_COLOR =
  "var(--chart-positive, var(--color-emerald-500))";
export const PROFIT_LOSS_NEGATIVE_COLOR =
  "var(--chart-negative, var(--color-red-500))";

const LEGEND_DIM_OPACITY = 0.25;

export function profitLossColor(value: number) {
  return value >= 0 ? PROFIT_LOSS_POSITIVE_COLOR : PROFIT_LOSS_NEGATIVE_COLOR;
}

export const PROFIT_LOSS_TOOLTIP_LABEL_FALLBACK = "Profit/Loss";

export function resolveProfitLossTooltipLabel(label: string) {
  const trimmed = label.trim();
  return trimmed || PROFIT_LOSS_TOOLTIP_LABEL_FALLBACK;
}

export interface ProfitLossLineProps {
  dataKey: string;
  /** @deprecated No effect; x comes from the chart's `xDataKey`. */
  xDataKey?: string;
  strokeWidth?: number;
  positiveColor?: string;
  negativeColor?: string;
  /** Curve function. Default: curveLinear */
  curve?: CurveFactory;
  /**
   * Fade the line stroke toward transparent at the chart edges.
   * Default: false
   */
  fadeEdges?: FadeEdges;
}

function segmentLegendIndex(isPositive: boolean) {
  return isPositive ? 0 : 1;
}

export function ProfitLossLine({
  dataKey,
  strokeWidth = 2.5,
  positiveColor = PROFIT_LOSS_POSITIVE_COLOR,
  negativeColor = PROFIT_LOSS_NEGATIVE_COLOR,
  curve = curveLinear,
  fadeEdges = false,
}: ProfitLossLineProps) {
  const { tooltipData } = useChart();
  const { hoveredIndex } = useProfitLossLegendHover();
  const { renderData, xScale, yScale, xAccessor, innerWidth } =
    useChartStable();
  const reactId = useId();
  const fadeSides = resolveFadeSides(fadeEdges);
  const fadeStops = fadeSides.any ? fadeGradientStops(fadeSides) : null;
  const positiveGradientId = `profit-loss-gradient-pos-${dataKey}-${reactId}`;
  const negativeGradientId = `profit-loss-gradient-neg-${dataKey}-${reactId}`;

  const focusedLegendIndex = useMemo(() => {
    if (hoveredIndex !== null) {
      return hoveredIndex;
    }
    if (!tooltipData) {
      return null;
    }
    const value = tooltipData.point[dataKey];
    if (typeof value !== "number") {
      return null;
    }
    return segmentLegendIndex(value >= 0);
  }, [dataKey, hoveredIndex, tooltipData]);

  const getX = useCallback(
    (d: Record<string, unknown>) => xScale(xAccessor(d)) ?? 0,
    [xAccessor, xScale]
  );
  const getY = useCallback(
    (d: Record<string, unknown>) => {
      const value = d[dataKey];
      return typeof value === "number" ? (yScale(value) ?? 0) : 0;
    },
    [dataKey, yScale]
  );

  // One continuous path, drawn twice and clipped above / below zero, so a
  // smooth curve stays smooth through each crossing (per-segment paths kink
  // there) and the colour switches exactly at the zero line.
  // Hover (tooltip / legend) re-renders only change opacity; reuse the path.
  const pathD = useMemo(
    () => linePathD(renderData, { curve, x: getX, y: getY }),
    [curve, getX, getY, renderData]
  );
  const [rangeBottom = 0, rangeTop = 0] = yScale.range();
  const plotTop = Math.min(rangeBottom, rangeTop);
  const plotBottom = Math.max(rangeBottom, rangeTop);
  const zeroY = Math.min(
    plotBottom,
    Math.max(plotTop, yScale(0) ?? plotBottom)
  );
  // Bleed so round caps and curve overshoot at the plot edges aren't clipped.
  const bleed = strokeWidth * 4;
  const clipX = -bleed;
  const clipWidth = innerWidth + bleed * 2;

  const sides = [
    {
      isPositive: true,
      clipId: `profit-loss-clip-pos-${dataKey}-${reactId}`,
      gradientId: positiveGradientId,
      color: positiveColor,
      y: plotTop - bleed,
      height: zeroY - (plotTop - bleed),
    },
    {
      isPositive: false,
      clipId: `profit-loss-clip-neg-${dataKey}-${reactId}`,
      gradientId: negativeGradientId,
      color: negativeColor,
      y: zeroY,
      height: plotBottom + bleed - zeroY,
    },
  ];

  return (
    <>
      <defs>
        {sides.map((side) => (
          <clipPath id={side.clipId} key={side.clipId}>
            <rect
              height={Math.max(0, side.height)}
              width={clipWidth}
              x={clipX}
              y={side.y}
            />
          </clipPath>
        ))}
        {fadeStops
          ? sides.map((side) => (
              <linearGradient
                gradientUnits="userSpaceOnUse"
                id={side.gradientId}
                key={side.gradientId}
                x1={0}
                x2={innerWidth}
                y1={0}
                y2={0}
              >
                {fadeStops.map((stop) => (
                  <stop
                    key={stop.offset}
                    offset={stop.offset}
                    style={{ stopColor: side.color, stopOpacity: stop.opacity }}
                  />
                ))}
              </linearGradient>
            ))
          : null}
      </defs>
      {sides.map((side) => {
        const isDimmed =
          focusedLegendIndex !== null &&
          focusedLegendIndex !== segmentLegendIndex(side.isPositive);
        return (
          <g
            clipPath={`url(#${side.clipId})`}
            key={side.clipId}
            opacity={isDimmed ? LEGEND_DIM_OPACITY : 1}
            style={{ transition: "opacity 0.2s ease-in-out" }}
          >
            <LinePath
              d={pathD}
              stroke={fadeStops ? `url(#${side.gradientId})` : side.color}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={strokeWidth}
            />
          </g>
        );
      })}
    </>
  );
}

ProfitLossLine.displayName = "ProfitLossLine";

type SegmentSign = "positive" | "negative";

export interface ProfitLossSegment {
  data: Record<string, unknown>[];
  isPositive: boolean;
}

function resolveSign(value: number, fallback: SegmentSign): SegmentSign {
  if (value > 0) {
    return "positive";
  }
  if (value < 0) {
    return "negative";
  }
  return fallback;
}

function findInitialSign(
  data: Record<string, unknown>[],
  dataKey: string
): SegmentSign {
  for (const row of data) {
    const value = row[dataKey];
    if (typeof value !== "number") {
      continue;
    }
    if (value > 0) {
      return "positive";
    }
    if (value < 0) {
      return "negative";
    }
  }
  return "positive";
}

function interpolateZeroCrossing(
  a: Record<string, unknown>,
  b: Record<string, unknown>,
  dataKey: string,
  xDataKey: string,
  xAccessor: (d: Record<string, unknown>) => Date
): Record<string, unknown> {
  const ya = a[dataKey] as number;
  const yb = b[dataKey] as number;
  const t = ya / (ya - yb);
  const start = xAccessor(a).getTime();
  const end = xAccessor(b).getTime();
  const crossDate = new Date(start + t * (end - start));

  return {
    ...a,
    [xDataKey]: crossDate,
    [dataKey]: 0,
  };
}

/** Split a single series into contiguous segments above/below zero. */
export function splitProfitLossSegments({
  data,
  dataKey,
  xDataKey = "date",
  xAccessor,
}: {
  data: Record<string, unknown>[];
  dataKey: string;
  xDataKey?: string;
  xAccessor: (d: Record<string, unknown>) => Date;
}): ProfitLossSegment[] {
  if (data.length === 0) {
    return [];
  }

  const segments: ProfitLossSegment[] = [];
  let currentSign = findInitialSign(data, dataKey);
  const firstPoint = data[0];
  if (!firstPoint) {
    return [];
  }
  let currentSegment: Record<string, unknown>[] = [firstPoint];

  for (let i = 0; i < data.length - 1; i++) {
    const a = data[i];
    const b = data[i + 1];
    if (!(a && b)) {
      continue;
    }
    const ya = a[dataKey] as number;
    const yb = b[dataKey] as number;

    if (
      typeof ya === "number" &&
      typeof yb === "number" &&
      ya !== 0 &&
      yb !== 0 &&
      Math.sign(ya) !== Math.sign(yb)
    ) {
      const cross = interpolateZeroCrossing(a, b, dataKey, xDataKey, xAccessor);
      currentSegment.push(cross);
      segments.push({
        data: currentSegment,
        isPositive: currentSign === "positive",
      });
      currentSegment = [cross, b];
      currentSign = resolveSign(yb, currentSign);
      continue;
    }

    currentSegment.push(b);
    if (typeof yb === "number" && yb !== 0) {
      currentSign = resolveSign(yb, currentSign);
    }
  }

  if (currentSegment.length > 0) {
    segments.push({
      data: currentSegment,
      isPositive: currentSign === "positive",
    });
  }

  return segments;
}

"use client";

import { createContext, type ReactNode, useContext } from "react";

interface ProfitLossLegendHoverContextValue {
  hoveredIndex: number | null;
}

const ProfitLossLegendHoverContext =
  createContext<ProfitLossLegendHoverContextValue | null>(null);

export function ProfitLossLegendHoverProvider({
  hoveredIndex,
  children,
}: {
  hoveredIndex: number | null;
  children: ReactNode;
}) {
  return (
    <ProfitLossLegendHoverContext.Provider value={{ hoveredIndex }}>
      {children}
    </ProfitLossLegendHoverContext.Provider>
  );
}

export function useProfitLossLegendHover(): ProfitLossLegendHoverContextValue {
  const context = useContext(ProfitLossLegendHoverContext);
  return context ?? { hoveredIndex: null };
}

"use client";

import { cn } from "@/lib/utils";
import { Legend, LegendItem, LegendLabel, LegendMarker } from "./legend/index";
import {
  PROFIT_LOSS_NEGATIVE_COLOR,
  PROFIT_LOSS_POSITIVE_COLOR,
} from "./profit-loss-line";

export const PROFIT_LOSS_LEGEND_ITEMS = [
  { label: "Profit", value: 0, color: PROFIT_LOSS_POSITIVE_COLOR },
  { label: "Loss", value: 0, color: PROFIT_LOSS_NEGATIVE_COLOR },
] as const;

export interface ProfitLossLegendProps {
  hoveredIndex?: number | null;
  onHoverChange?: (index: number | null) => void;
  align?: "start" | "center" | "end";
  className?: string;
}

const LEGEND_ALIGN_CLASSES: Record<
  NonNullable<ProfitLossLegendProps["align"]>,
  string
> = {
  start: "justify-start",
  center: "justify-center",
  end: "justify-end",
};

export function ProfitLossLegend({
  hoveredIndex = null,
  onHoverChange,
  align = "start",
  className,
}: ProfitLossLegendProps) {
  return (
    <div
      className={cn(
        "flex w-full shrink-0 px-1 py-2",
        LEGEND_ALIGN_CLASSES[align],
        className
      )}
      data-chart-legend=""
    >
      <Legend
        className="flex-row flex-wrap gap-4"
        hoveredIndex={hoveredIndex}
        items={[...PROFIT_LOSS_LEGEND_ITEMS]}
        onHoverChange={onHoverChange}
      >
        <LegendItem className="flex items-center gap-2">
          <LegendMarker className="h-2.5 w-2.5" />
          <LegendLabel className="text-xs" />
        </LegendItem>
      </Legend>
    </div>
  );
}
